3	#include <utility>
4	#include <vector>
5	
6	#include "file_digest_internal.h"
7	
8	namespace branchaudit {
9	
10	Digest merkle_empty_root() {
11	    // SHA-256 对空字节序列（不追加任何 Merkle 前缀）。
12	    return Sha256{}.final();
13	}
14	
15	Digest merkle_leaf(const unsigned char* data, std::size_t size) {
16	    Sha256 sha;
17	    const unsigned char prefix = 0x00;
18	    sha.update(&prefix, 1);
19	    sha.update(data, size);
20	    return sha.final();
21	}
22	
23	Digest merkle_parent(const Digest& left, const Digest& right) {
24	    Sha256 sha;
25	    const unsigned char prefix = 0x01;
26	    sha.update(&prefix, 1);
27	    sha.update(left.data(), left.size());
28	    sha.update(right.data(), right.size());
29	    return sha.final();
30	}
31	
32	namespace {
33	
34	// 流式计算单个文件的叶子摘要 SHA-256(0x00 || file bytes)。
35	// 定位、打开、分块读取与失败处理与 sha256_file 共用同一实现：唯一区别是
36	// 在文件字节之前加入一次单个 0x00 前缀字节（空文件也存在，且不随分块重复）。
37	FileHashResult leaf_file(const std::filesystem::path& path) {
38	    static constexpr unsigned char kLeafPrefix = 0x00;
39	    return internal::sha256_file_digest(path, &kLeafPrefix);
40	}
41	
42	// 计算有序批次的叶子层。严格按 paths 下标顺序：不排序、不去重。
43	// 任一文件失败立即返回该错误，不读取也不使用其后的任何文件。
44	std::string leaf_level(const std::vector<std::filesystem::path>& paths,
45	                       std::vector<Digest>& level) {
46	    level.clear();
47	    level.reserve(paths.size());
48	    for (const std::filesystem::path& path : paths) {
49	        FileHashResult leaf = leaf_file(path);
50	        if (!leaf.ok()) {
51	            return std::move(leaf.error);
52	        }
53	        level.push_back(leaf.digest);
54	    }
55	    return {};
56	}
57	
58	// 批次合并规则（root 与 prove 共用的唯一一份实现）：对当前层做一次相邻
59	// 配对——相邻节点按先左后右两两用 merkle_parent 合并；若该层节点数为
60	// 奇数，最后一个没有伙伴的节点摘要原样进入上一层（不复制、不补零）。
61	// 输入层不被修改，返回合并后的上一层；输入只有一个节点时返回的层同样
62	// 只有该节点本身。
63	std::vector<Digest> combine_level(const std::vector<Digest>& level) {
64	    std::vector<Digest> next;
65	    const bool odd = (level.size() % 2) != 0;
66	    next.reserve(level.size() / 2 + (odd ? 1 : 0));
67	    for (std::size_t i = 0; i + 1 < level.size(); i += 2) {
68	        next.push_back(merkle_parent(level[i], level[i + 1]));
69	    }
70	    if (odd) {
71	        next.push_back(level.back());
72	    }
73	    return next;
74	}
75	
76	}  // namespace
77	
78	FileHashResult merkle_root_files(const std::vector<std::filesystem::path>& paths) {
79	    FileHashResult result;
80	
81	    // 没有文件：空字节序列的 SHA-256。
82	    if (paths.empty()) {
83	        result.digest = merkle_empty_root();
84	        return result;
85	    }
86	
87	    // 叶子层。
88	    std::vector<Digest> level;
89	    result.error = leaf_level(paths, level);
90	    if (!result.ok()) {
91	        return result;
92	    }
93	
94	    // 逐层相邻配对直到只剩一个根；配对与奇数末节点原样提升的规则由
95	    // combine_level 唯一实现，prove 沿同一函数走，两条路径不会出现规则漂移。
96	    while (level.size() > 1) {
97	        level = combine_level(level);
98	    }
99	
100	    result.digest = level.front();
101	    return result;
102	}
103	
104	MerkleProofResult merkle_proof_file(
105	        const std::vector<std::filesystem::path>& paths,
106	        std::uint64_t leaf_index) {
107	    MerkleProofResult result;
108	
109	    // 位置必须落在批次内；空批次没有任何合法位置。
110	    if (leaf_index >= paths.size()) {
111	        result.error = "leaf index " + std::to_string(leaf_index) +
112	                       " out of range for batch of " +
113	                       std::to_string(paths.size()) + " file(s)";
114	        return result;
115	    }
116	
117	    // 叶子层：与 merkle_root_files 完全相同的文件与顺序规则。
118	    std::vector<Digest> level;
119	    result.error = leaf_level(paths, level);
120	    if (!result.ok()) {
121	        return result;
122	    }
123	
124	    MerkleProof& proof = result.proof;
125	    proof.leaf_count = paths.size();
126	    proof.leaf_index = leaf_index;
127	    proof.leaf = level[static_cast<std::size_t>(leaf_index)];
128	
129	    // 沿被选位置逐层向上：每层只记录实际存在的兄弟；奇数末节点原样
130	    // 提升的层没有兄弟，不添加记录（不复制末节点、不补零）。该层如何
131	    // 合并与 root 完全相同——两者都调用同一份 combine_level。
132	    std::size_t idx = static_cast<std::size_t>(leaf_index);
133	    while (level.size() > 1) {
134	        if (idx % 2 == 0) {
135	            if (idx + 1 < level.size()) {
136	                proof.siblings.push_back(
137	                    {MerkleSibling::Side::right, level[idx + 1]});
138	            }
139	            // idx 是奇数层的末节点：经 combine_level 原样提升，无兄弟记录。
140	        } else {
141	            proof.siblings.push_back(
142	                {MerkleSibling::Side::left, level[idx - 1]});
143	        }
144	
145	        idx /= 2;
146	        level = combine_level(level);
147	    }
148	
149	    proof.root = level.front();
150	    return result;
151	}
152	
153	MerkleVerifyResult merkle_verify_proof(const MerkleProof& proof,
154	                                       const Digest& trusted_root,
155	                                       const Digest& content_leaf) {
156	    MerkleVerifyResult result;
157	
158	    // 空批次没有任何成员；位置必须从 0 开始并落在批次内。
159	    if (proof.leaf_count == 0) {
160	        result.error =
161	            "proof rejected: empty batch (leaf_count is 0) has no members";
162	        return result;
163	    }
164	    if (proof.leaf_index >= proof.leaf_count) {
165	        result.error =
166	            "proof rejected: leaf_index " +
167	            std::to_string(proof.leaf_index) + " is out of range for leaf_count " +
168	            std::to_string(proof.leaf_count);
169	        return result;
170	    }
171	
172	    // 条件 1：待验证内容的叶子摘要必须与证明中的叶子完全一致。
173	    // content_leaf 按叶子规则带单个 0x00 前缀；普通文件摘要（无此前缀）
174	    // 不可能与真实叶子相等，不能借此通过。
175	    if (content_leaf != proof.leaf) {
176	        result.error =
177	            "proof rejected: supplied content leaf digest does not match the "
178	            "leaf digest in the proof";
179	        return result;
180	    }
181	
182	    // 条件 4 + 条件 3 的折叠：兄弟的方向、数量与从叶子向根的次序必须严格
183	    // 符合 (leaf_count, leaf_index) 描述的位置；在逐层核对的同时按
184	    // SHA-256(0x01||left||right) 折叠。不能只在最后比对摘要——结构不符
185	    // （侧向错、缺项、多项、次序错）即使凑出相等摘要也必须拒绝。
186	    //
187	    // 各层节点数只做纯 uint64 模拟，绝不按 leaf_count 分配内存；上一层
188	    // 大小为 ceil(n/2)，写成 n - n/2 —— n 为奇数时 (n+1)/2 在
189	    // n=UINT64_MAX 处会回绕，n - n/2 不会。层数关于 n 有界（至多 64 层），
190	    // 因此最大可表示的合法计数也立即得到确定结果。
191	    std::uint64_t level_size = proof.leaf_count;
192	    std::uint64_t pos = proof.leaf_index;
193	    std::uint64_t tree_level = 0;  // 叶子之上第一层为 0，仅用于错误信息
194	    std::size_t consumed = 0;
195	    Digest node = content_leaf;
196	
197	    while (level_size > 1) {
198	        // 与 merkle_proof_file 的记录规则完全一致：偶数位置且该位置是
199	        // 奇数层末节点时，节点原样提升，本层没有兄弟、不消费记录；
200	        // 偶数且右侧仍有伙伴 -> 必须有 right 兄弟；奇数位置 -> 必须有
201	        // left 兄弟（pos>=1，左侧伙伴必然存在）。
202	        // 写成 pos == level_size - 1 而非 pos + 1 >= level_size：
203	        // level_size > 1 保证减法安全，而 pos+1 在 pos=UINT64_MAX 时会
204	        // 无符号回绕成 0，恰好把“末节点提升”误判成“右侧有兄弟”。
205	        const bool promoted_without_sibling =
206	            (pos % 2 == 0) && (pos == level_size - 1);
207	
208	        if (!promoted_without_sibling) {
209	            if (consumed >= proof.siblings.size()) {
210	                result.error =
211	                    "proof rejected: missing required sibling at tree level " +
212	                    std::to_string(tree_level) + " for leaf_index " +
213	                    std::to_string(proof.leaf_index) + " of leaf_count " +
214	                    std::to_string(proof.leaf_count);
215	                return result;
216	            }
217	
218	            const MerkleSibling& sibling = proof.siblings[consumed];
219	
220	            // side 只能是 left 或 right：证明结构可能由调用方自行构造，
221	            // 非法枚举值也必须明确拒绝，不能落入任一分支碰运气。
222	            bool sibling_on_right;
223	            if (sibling.side == MerkleSibling::Side::right) {
224	                sibling_on_right = true;
225	            } else if (sibling.side == MerkleSibling::Side::left) {
226	                sibling_on_right = false;
227	            } else {
228	                result.error =
229	                    "proof rejected: sibling at tree level " +
230	                    std::to_string(tree_level) +
231	                    " has an invalid side (only left or right is allowed)";
232	                return result;
233	            }
234	
235	            const bool expected_on_right = (pos % 2 == 0);
236	            if (sibling_on_right != expected_on_right) {
237	                result.error =
238	                    "proof rejected: sibling at tree level " +
239	                    std::to_string(tree_level) + " is on the " +
240	                    (sibling_on_right ? "right" : "left") +
241	                    " side, but the position in the batch requires it on the " +
242	                    (expected_on_right ? "right" : "left");
243	                return result;
244	            }
245	
246	            node = sibling_on_right
247	                       ? merkle_parent(node, sibling.digest)
248	                       : merkle_parent(sibling.digest, node);
249	            ++consumed;
250	        }
251	        // 原样提升或正常配对后，被选位置在上一层的下标都是 floor(pos/2)；
252	        // pos 始终小于 level_size，不会触及 UINT64_MAX 回绕。
253	        pos /= 2;
254	        ++tree_level;
255	        const std::uint64_t half = level_size / 2;
256	        level_size -= half;  // ceil(level_size/2)，无回绕。
257	    }
258	
259	    // 到达根后不得还有多余兄弟。
260	    if (consumed != proof.siblings.size()) {
261	        result.error =
262	            "proof rejected: proof carries " +
263	            std::to_string(proof.siblings.size()) +
264	            " sibling(s), but the batch position requires exactly " +
265	            std::to_string(consumed);
266	        return result;
267	    }
268	
269	    // 条件 2：信任锚只来自调用方单独传入的可信根；证明自报的 root 不能
270	    // 充当信任依据——属于另一批次的证明即使内部自洽也在此被拒。
271	    if (proof.root != trusted_root) {
272	        result.error =
273	            "proof rejected: root claimed by the proof does not match the "
274	            "trusted batch root";
275	        return result;
276	    }
277	
278	    // 条件 3：兄弟必须真的把内容叶子折叠到可信根（防止 root 字段被改成
279	    // 可信根、但兄弟链与叶子并不相容的证明）。
280	    if (node != trusted_root) {
281	        result.error =
282	            "proof rejected: the supplied siblings do not combine the content "
283	            "leaf into the trusted batch root";
284	        return result;
285	    }
286	
287	    result.valid = true;
288	    return result;
289	}
290	
291	}  // namespace branchaudit
