    const std::uint64_t expected_leaf_index = 2;

    // 为从零开始的位置 2 生成证明。
    branchaudit::MerkleProofResult proof_result =
        branchaudit::merkle_proof_file(batch, /*leaf_index=*/2);
    if (!proof_result.ok()) {
        std::cerr << "prove failed: " << proof_result.error << '\n';
        return 1;
    }
    const branchaudit::MerkleProof proof = proof_result.proof;

    // 内容叶子：来自被选文件（位置 2 的 c.bin）的全部字节。
    std::ifstream in(batch[2], std::ios::binary);
    const std::string selected{std::istreambuf_iterator<char>(in),
                               std::istreambuf_iterator<char>()};
    const branchaudit::Digest content_leaf = branchaudit::merkle_leaf(
        reinterpret_cast<const unsigned char*>(selected.data()), selected.size());

    // 第一次：原证明（leaf_count=3, leaf_index=2）。
    const branchaudit::MerkleVerifyResult original =
        branchaudit::merkle_verify_proof(proof, trusted_root, content_leaf);
    std::cout << "original proof (leaf_count=" << proof.leaf_count
              << ", leaf_index=" << proof.leaf_index << "): "
              << (original.ok() ? "PASS" : "FAIL") << '\n';

    // 第二次：仅把证明自报的 leaf_count 改为 2、leaf_index 改为 1，
    // 根、叶子与兄弟记录原样保留。
    branchaudit::MerkleProof renumbered = proof;
    renumbered.leaf_count = 2;
    renumbered.leaf_index = 1;
    const branchaudit::MerkleVerifyResult renumbered_result =
        branchaudit::merkle_verify_proof(renumbered, trusted_root, content_leaf);
    std::cout << "renumbered proof (leaf_count=" << renumbered.leaf_count
              << ", leaf_index=" << renumbered.leaf_index << "): "
              << (renumbered_result.ok() ? "PASS" : "FAIL") << '\n';

    // 业务侧位置认定：把证明自报的数字与独立保存的批次信息比对。
    // 库校验通过不等于位置可信；数字不一致时必须拒绝位置认定。
    const bool position_matches =
        renumbered.leaf_count == expected_leaf_count &&
        renumbered.leaf_index == expected_leaf_index;
    std::cout << "renumbered proof matches independently stored batch info: "
              << (position_matches ? "yes" : "no")
              << " -> position claim must be "
              << ((position_matches && renumbered_result.ok()) ? "accepted"
                                                               : "rejected")
              << '\n';
    return 0;
}

